describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: 10% of 1000 = 100, plus 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // Sum is 1300, exceeds 1000 — that's fine, Cart clamps
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200, remaining 800
          new PercentageDiscountPolicy(10), // 10% of 800 = 80
        ],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "chain",
      );
      expect(policyA.computeDiscountCents(1000)).toBe(280);
      expect(policyB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops reducing once remaining hits zero", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // takes all 1000
          new FixedAmountDiscountPolicy(500), // remaining is 0, contributes 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

