describe("Cart — checkout()", () => {
  it("returns totals and lines for simple checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(750),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout({ priceFetcher });
    // price refreshed to 750 * 2 = 1500
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(750);
  });

  it("checks inventory and passes for available items", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(2);
      expect(ie.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1, // requested 3 but only 1 available
      }),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 3);
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(3);
      expect(ie.available).toBe(1);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US-TX" });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-TX");
  });

  it("combines discount + asyncTax + shipping in checkout", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
      region: "US",
    });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=200, discountedSubtotal=800
    // tax = 10% of 800 = 80
    // shipping = 500
    // total = 800 + 80 + 500 = 1380
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1380);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API error")),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API error",
    );
  });

  it("first inventory denial wins when multiple items fail", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: false, reason: "out of stock A" })
        .mockResolvedValueOnce({ available: false, reason: "out of stock B" }),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    cart.add(product("b", 600), 1);
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // First line checked should be "a"
      expect((err as InventoryError).message).toBe("out of stock A");
    }
  });

  it("checkout with all collaborators at once", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(800),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const cart = new Cart({ region: "FR" });
    cart.add(product("a", 500), 2);
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // refreshed price: 800 * 2 = 1600
    // no discount (default NoDiscountPolicy)
    // tax: 5% of 1600 = 80
    // shipping: FreeShippingCalculator = 0
    expect(result.totals.subtotalCents).toBe(1600);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.totalCents).toBe(1680);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("uses sync tax calculator when no asyncTaxProvider", async () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.taxCents).toBe(50);
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative percent"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
      [-Infinity, "-Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      // 15% of 999 = 149.85 → 149
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotal correctly", () => {
      const policy = new PercentageDiscountPolicy(25);
      // 25% of 100_000_00 = 25_000_00
      expect(policy.computeDiscountCents(10_000_00)).toBe(2_500_00);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns full amount when subtotal exceeds discount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps discount at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1500);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns subtotal when discount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: 10% of 1000 = 100, plus 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // Sum is 1300, exceeds 1000 — that's fine, Cart clamps
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200, remaining 800
          new PercentageDiscountPolicy(10), // 10% of 800 = 80
        ],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "chain",
      );
      expect(policyA.computeDiscountCents(1000)).toBe(280);
      expect(policyB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops reducing once remaining hits zero", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // takes all 1000
          new FixedAmountDiscountPolicy(500), // remaining is 0, contributes 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

