toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type {
  PriceFetcher,
  InventoryChecker,
} from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

// -- helpers ---------------------------------------------------------------

const product = (
  id: string,
  unitPriceCents: number,
  extra: Partial<Product> = {},
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  ...extra,
});

// -- Cart line management --------------------------------------------------

describe("Cart — line management", () => {
  it("starts empty with 0 items", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding same product twice", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nope")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 1)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    cart.add(product("b", 200), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy (mutation safety)", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // internal state should be unchanged
    const snap2 = cart.snapshot();
    expect(snap2[0]!.quantity).toBe(1);
    expect(snap2[0]!.product.unitPriceCents).toBe(100);
  });
});

// -- Cart totals (pricing pipeline) ----------------------------------------

describe("Cart — totals (pricing pipeline)", () => {
  it("empty cart produces all-zero totals", () => {
    const cart = new Cart();
    expect(cart.totals()).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(300);
    expect(totals.subtotalCents).toBe(1000);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps over-subtotal discount to subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(5000),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("taxes the discounted subtotal, not the raw subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // Discounted subtotal = 1000 - 200 = 800
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("computes shipping against discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // discountedSubtotal = 1000 - 200 = 800
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
    expect(totals.shippingCents).toBe(500);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discountedSubtotal=900
    // total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
  });

  it("clamps negative tax to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

// -- Cart.checkout() -------------------------------------------------------

describe("Cart — checkout()", () => {
  it("returns totals and lines for simple checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(750),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout({ priceFetcher });
    // price refreshed to 750 * 2 = 1500
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(750);
  });

  it("checks inventory and passes for available items", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000);
